const express = require('express');
const { ReportCardDb } = require('../services/sis');

const app = express();
const schoolSubApp = express({ mergeParams: true });

app.use('/districts/:districtId/schools', (req, res, next) => {
  if (!req.session || !req.session.staffId) {
    return res.status(401).json({ error: 'Staff authentication required' });
  }

  // Validate staff jurisdiction over district
  if (req.session.districtId !== req.params.districtId && req.session.role !== 'STATE_AUDITOR') {
    return res.status(403).json({ error: 'Access denied: district jurisdiction mismatch' });
  }
  next();
}, schoolSubApp);

schoolSubApp.get('/:schoolId/students/:studentId/report-card', async (req, res) => {
  // Query report card scoped strictly to district, school, and student
  const reportCard = await ReportCardDb.findOne({
    studentId: req.params.studentId,
    schoolId: req.params.schoolId,
    districtId: req.params.districtId
  });

  if (!reportCard) {
    return res.status(404).json({ error: 'Report card not found in this school' });
  }

  res.json({
    studentId: req.params.studentId,
    gpa: reportCard.gpa,
    disciplinaryRecords: reportCard.disciplinaryActions,
    grades: reportCard.letterGrades
  });
});

app.listen(5000);
